function calculate() {

  let total = 0;

  for (let i = 0; i < 5e9; i++) {

    total += i;

  }

  return total;

}

myDisplayer("Calculating...");

let result = calculate();

myDisplayer(result);

myDisplayer("Start");

setTimeout(function () {

  myDisplayer("Timer")}, 1000);

let i = 5e9;

while (--i > 0);

myDisplayer("Finished");

