onmessage = function(event) {

  const limit = event.data;

  let total = 0;

  for (let i = 0; i <= limit; i++) {

    total += i;

    if (i % 10000000 === 0) {

      postMessage("Progress: " + Math.round(i / limit * 100) + "%");

    }

  }

  postMessage("Result: " + total);

};

